import React from "react";
import "./item.css"; // Make sure to create this CSS file

/**
 * RSS Feed Item Component
 * 
 * Props:
 * - title: string
 * - link: string
 * - pubDate: string
 * - description: string (HTML content from RSS <description>)
 */
export default function Item({ title, date, body }) {
  const formattedDate = date ? new Date(date).toLocaleString() : null;

  return (
    <div className="item">
      <div className="item-card">
        <div className="item-card-header">
	  <h1> {title}</h1>
	  { formattedDate && <div className="item-date">
              📅 <span>{formattedDate}</span>
            </div> }
        </div>

        <div
          className="item-description"
          dangerouslySetInnerHTML={{ __html: body }}
        />
      </div>
    </div>
  );
}
